<?php
namespace Delnavazan\Platform\Portals;

final class PortalCapabilityService {
    private function table(string $name): string { global $wpdb; return $wpdb->prefix . 'dzn_' . $name; }
    private function digest(string $value): string { return hash_hmac('sha256', $value, wp_salt('dzn_portal_capability_public')); }
    private function uid(): string { return substr(str_replace('-', '', wp_generate_uuid4()), 0, 26); }
    /**
     * §15.6 — every capability transaction boundary is checked and fails closed. A failed `START TRANSACTION`
     * never opens work, a failed `COMMIT` is the declared persistence failure (never a returned success, never a
     * `302` redirect), and a `ROLLBACK` is issued only for a transaction this call actually opened.
