    private function commit():void { global $wpdb; if($wpdb->query('COMMIT')===false)throw new \RuntimeException('portal_capability_persistence_failed'); }
    private function rollback():void { global $wpdb; $wpdb->query('ROLLBACK'); }
    private function requireCommandKey(?string $key): string { $key=trim((string)$key); if($key==='')throw new \InvalidArgumentException('portal_confirmation_required'); return $key; }
    private function owner(int $lesson,int $schedule,string $purpose,?int $student,bool $required=true):array { return PortalOwnerPorts::capability()->binding($lesson,$schedule,$purpose,$student,$required); }
    private function root(int $lesson):void { if($lesson<1)throw new \InvalidArgumentException('portal_parent_not_live'); global $wpdb; $table=$this->table('portal_lesson_capability_roots'); if($wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$table}(lesson_id,created_at,created_by) VALUES(%d,%s,%d)",$lesson,gmdate('Y-m-d H:i:s'),get_current_user_id()))===false)throw new \RuntimeException('portal_capability_persistence_failed'); if(!$wpdb->get_row($wpdb->prepare("SELECT id FROM {$table} WHERE lesson_id=%d FOR UPDATE",$lesson)))throw new \RuntimeException('portal_capability_persistence_failed'); }
    private function inputs(int $lesson,int $schedule,string $purpose,int $expires,string $target):array { if(!in_array($purpose,array(PortalRule::JOIN,PortalRule::ABSENCE),true))throw new \InvalidArgumentException('portal_vocabulary_member_not_allowed'); if($expires<=time())throw new \InvalidArgumentException('portal_capability_expiry_missing'); if($expires>time()+PortalRule::MAX_CAPABILITY_TTL_SECONDS)throw new \InvalidArgumentException('portal_capability_ttl_not_allowed'); if($purpose===PortalRule::ABSENCE)$target='https://meet.google.com/'; $parts=parse_url($target); $host=strtolower((string)($parts['host']??'')); if($purpose===PortalRule::JOIN&&(!$parts||($parts['scheme']??'')!=='https'||!in_array($host,PortalRule::SAFE_JOIN_HOSTS,true)))throw new \InvalidArgumentException($target===''?'portal_join_target_not_declared':'portal_join_target_not_allowlisted'); return array($target,$host); }
    private function seal(string $value):array { $nonce=random_bytes(12);$tag='';$cipher=openssl_encrypt($value,'aes-256-gcm',hash('sha256',wp_salt('secure_auth').'dzn_portal_join_target',true),OPENSSL_RAW_DATA,$nonce,$tag);if($cipher===false)throw new \RuntimeException('portal_join_target_unavailable');return array(base64_encode($cipher.$tag),base64_encode($nonce)); }
