    private function binding(array $owner,string $purpose,int $generation,string $expiry):string { return PortalRule::CAPABILITY_BINDING_VERSION.'|'.$purpose.'|'.$owner['lesson_uid'].'|'.$owner['schedule_version_uid'].'|'.$generation.'|'.$expiry; }
    private function command(int $lesson,string $purpose,string $operation,string $reason,?int $result,string $state,string $key,string $payload,?int $expectedId=null,?int $expectedGeneration=null,?string $expectedState=null,string $host=''):void { if(!in_array($operation,PortalRule::CAPABILITY_COMMAND_OPERATIONS,true))$operation='unknown';PortalRule::reason($reason);global $wpdb;$ok=$wpdb->insert($this->table('portal_public_capability_commands'),array('uid'=>$this->uid(),'command_domain'=>'portal_capability','operation'=>$operation,'command_key_digest'=>$this->digest($key),'command_payload_digest'=>hash('sha256',$payload),'lesson_id'=>max(0,$lesson),'purpose'=>$purpose,'expected_capability_id'=>$expectedId,'expected_generation'=>$expectedGeneration,'expected_state'=>$expectedState,'join_target_host'=>$host===''?null:$host,'reason_code'=>$reason,'result_capability_id'=>$result,'result_state'=>$state,'created_at'=>gmdate('Y-m-d H:i:s'),'created_by'=>get_current_user_id()));if($ok===false)throw new \RuntimeException('portal_capability_persistence_failed'); }
    /**
     * A refused command occupies the same durable command key as an accepted command.
     * Reusing that key with different facts is a replay conflict, never a second synthetic key.
     */
    public function recordRefusal(string $operation,?string $key,string $payload,string $reason,int $lesson=0,string $purpose=''):string { $reason=in_array($reason,PortalRule::EXCEPTION_REASON_CODES,true)?$reason:'portal_upstream_aggregate_invalid';$operation=in_array($operation,PortalRule::CAPABILITY_COMMAND_OPERATIONS,true)?$operation:'unknown';$purpose=in_array($purpose,PortalRule::PURPOSES,true)?$purpose:PortalRule::COMMAND_PURPOSE_UNKNOWN;$key=trim((string)$key);if($key==='')$key='refusal|'.$operation.'|'.$purpose.'|'.$lesson.'|'.hash('sha256',$payload.'|'.$reason);global $wpdb;$opened=false;$this->begin();$opened=true;try{$digest=$this->digest($key);$payloadDigest=hash('sha256',$payload);$existing=$wpdb->get_row($wpdb->prepare("SELECT command_payload_digest,operation,lesson_id,purpose,result_state,reason_code FROM {$this->table('portal_public_capability_commands')} WHERE command_key_digest=%s FOR UPDATE",$digest));if(!$existing){$this->command($lesson,$purpose,$operation,$reason,null,'refused',$key,$payload);$recordedReason=$reason;}else{if((string)$existing->operation!==$operation||(int)$existing->lesson_id!==$lesson||(string)$existing->purpose!==$purpose||!hash_equals((string)$existing->command_payload_digest,$payloadDigest)||(string)$existing->result_state!=='refused')throw new \InvalidArgumentException('command_replay_conflict');$recordedReason=(string)$existing->reason_code;if(!in_array($recordedReason,PortalRule::EXCEPTION_REASON_CODES,true))throw new \InvalidArgumentException('command_replay_conflict');}$this->commit();return$recordedReason;}catch(\Throwable$e){if($opened)$this->rollback();throw$e;} }
