    private function event(int $lesson,int $capability,string $purpose,int $generation,string $type,string $reason):void { PortalRule::reason($reason);global $wpdb;$sequence=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(event_sequence),0)+1 FROM {$this->table('portal_public_capability_events')} WHERE lesson_id=%d FOR UPDATE",$lesson));if($wpdb->insert($this->table('portal_public_capability_events'),array('uid'=>$this->uid(),'lesson_id'=>$lesson,'capability_id'=>$capability,'event_sequence'=>$sequence,'event_type'=>$type,'purpose'=>$purpose,'generation'=>$generation,'reason_code'=>$reason,'evidence_channel'=>'admin','evidence_reference_digest'=>hash('sha256',$type.'|'.$capability.'|'.$sequence),'recorded_at'=>gmdate('Y-m-d H:i:s'),'created_at'=>gmdate('Y-m-d H:i:s'),'created_by'=>get_current_user_id()))===false)throw new \RuntimeException('portal_capability_persistence_failed'); }
    /** The rotate path calls this primitive directly; it therefore creates no mint command. */
    private function createCapability(int $lesson,int $schedule,string $purpose,int $expires,string $target,?int $student):array { [$target,$host]=$this->inputs($lesson,$schedule,$purpose,$expires,$target);[$cipher,$nonce]=$this->seal($target);global $wpdb;$owner=$this->owner($lesson,$schedule,$purpose,$student);if($purpose===PortalRule::ABSENCE)$student=(int)$owner['student_id'];$generation=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(generation),0)+1 FROM {$this->table('portal_public_capabilities')} WHERE lesson_id=%d AND purpose=%s FOR UPDATE",$lesson,$purpose));if($generation<1)throw new \InvalidArgumentException('portal_capability_generation_conflict');$expiry=gmdate('Y-m-d H:i:s',$expires);$handle=bin2hex(random_bytes(PortalRule::HANDLE_ENTROPY_BYTES));$signature=hash_hmac('sha256',$this->binding($owner,$purpose,$generation,$expiry),wp_salt('dzn_portal_capability_public'));$data=array('uid'=>$this->uid(),'lesson_id'=>$lesson,'schedule_version_id'=>$schedule,'subject_student_id'=>$student,'purpose'=>$purpose,'generation'=>$generation,'handle_digest'=>$this->digest($handle),'token_digest'=>$this->digest($handle.$signature),'join_target_ciphertext'=>$cipher,'join_target_nonce'=>$nonce,'join_target_key_version'=>'dzn_portal_join_target','join_target_cipher_version'=>'aes-256-gcm-v1','join_target_host'=>$host,'state'=>'active','active_slot'=>1,'issued_at'=>gmdate('Y-m-d H:i:s'),'expires_at'=>$expiry,'reason_code'=>'phase_w_declared_default','created_at'=>gmdate('Y-m-d H:i:s'),'created_by'=>get_current_user_id());if($wpdb->insert($this->table('portal_public_capabilities'),$data)===false)throw new \RuntimeException('portal_capability_persistence_failed');$id=(int)$wpdb->insert_id;return array('capability_id'=>$id,'handle'=>$handle,'token'=>$handle.$signature,'url'=>home_url('/wp-json/delnavazan-platform/v1/portal/'.($purpose===PortalRule::ABSENCE?'absence':'join').'?handle='.rawurlencode($handle).'&token='.rawurlencode($handle.$signature)),'state'=>'active